var npcId=2012012, maps=[200000000], entries=[[3051, 0, "莉萨的介绍", ["喂！旅行者～如果有空的话来听听我的故事好吗~"], "有了莉萨介绍，决定去见在冰封雪域的斯卡德。", ["因为您看起来非常强，所以才叫你的。在#b冰峰雪域#k住着叫做#b斯卡德勒#k的一个人。最近想要做件新毛皮大衣来换掉原先旧的，不过为了得到最好的毛皮材料就要狩猎强大的怪物。", "所以那个#b斯卡德勒#k拜托我，如果见到强者的话向他推荐呢！请带上我给您的介绍信去见一下#b斯卡德勒#k吧。会对你很有帮助的！"], {}, []], [3054, 1, "妖精的号角", ["这真是让我既紧张又期待的工作啊，那就让我们开始吧？哦，首先在那之前要确认一下带来的材料。"], "只要有妖精的号角，就可以和波达自由对话... 莉萨说可以帮忙制作号角，那我得准备一下材料了！ \n\n#t4000073# #b#c4000073#/100#k\n#t4003004# #b#c4003004#/20#k\n#t4000021# #b#c4000021#/10#k", ["呼呼～弄来了材料都很不错哦。真是让我既紧张又期待的工作啊。", "多么漂亮的号角啊，虽然是我做出来的，看来还是很不错嘛。有了这个就能听懂波达所说的话吧。快去看看，帮助那可怜的波达吧。"], {}, []], [3054, 0, "妖精的号角", ["真的想听懂波达所说的话吗？倒是有一个方法。… 只要有妖精们才有的妖精的号角，就能听懂波达所说的话了…", "不过，妖精们应该不会轻易给你自己的号角。妖精们从来都不怎么信任人类… 嗯… 嗯… 我倒是见过妖精的号角，也许能做出来。愿意弄来一些材料吗？"], "只要有妖精的号角，就可以和波达自由对话... 莉萨说可以帮忙制作号角，那我得准备一下材料了！ \n\n#t4000073# #b#c4000073#/100#k\n#t4003004# #b#c4003004#/20#k\n#t4000021# #b#c4000021#/10#k", ["所需的材料是独角狮硬角 100个，粗羽毛 20个，动物皮 10张。", "不知为什么想起了以前的事情，觉得做这事情应该很有趣呢。请快点弄来材料吧！去怪物居住的庭院就能弄到的。"], {}, []], [3055, 0, "妖精的号角 Ⅱ", ["如果人类使用妖精的号角话会发生什么事情呢？？因为这是妖精的东西，如果人类使用的话可能会发生不可预知的事情..就算这样也要试一下吗？"], "试着对波达使用妖精的号角吧！", ["好的！那就快去波达那里吹这个号角吧！妖精不会喜欢人类使用那个号角的…"], {}, []], [3057, 1, "莉萨的特殊治疗剂Ⅱ", ["真的？把所有材料都弄来了吗？那~ 现在只剩下赶紧把药做出来的事情了。对了，在那之前先让我确认一下材料到底对不对吧？", ".. 将各种药水好好搅拌… 比例很重要… 稍微煮一下… 再放一些解毒剂… 终于泛出光芒了... 多么神秘的色彩啊…", "最后再放进蝴蝶精的触角~"], "为了制作莉萨的特殊治疗剂需要橙色药水40个和蓝色药水20个，解毒剂1个… 还有..蝴蝶精的触角1个，不过要抓住具有特殊能力的蝴蝶精可不是件容易的事情。\n\n#t2000001# #b#c2000001#/40#k\n#t2000003# #b#c2000003#/20#k\n#t2050000# #b#c2050000#/1#k\n#t4000068# #b#c4000068#/1#k", ["随着砰!!.....的一声冒出了蒸汽，诱人的香气向四处扩散。"], {}, []], [3057, 0, "莉萨的特殊治疗剂Ⅱ", ["对于被天空之城村庄附近的怪物袭击所受的伤，只有用我的特殊治疗剂才有效。 我就算闭上眼睛也能做得出来。怎么样？想不想制作啊？"], "为了制作莉萨的特殊治疗剂需要橙色药水40个和蓝色药水20个，解毒剂1个… 还有..蝴蝶精的触角1个，不过要抓住具有特殊能力的蝴蝶精可不是件容易的事情。\n\n#t2000001# #b#c2000001#/40#k\n#t2000003# #b#c2000003#/20#k\n#t2050000# #b#c2050000#/1#k\n#t4000068# #b#c4000068#/1#k", ["制作的材料需要橙色药水 40个和蓝色药水 20个和解毒剂 1个，还有蝴蝶精的触角 1个。其中蝴蝶精的触角并不是轻易就能弄到的。蝴蝶精是拥有特殊能力的怪物。", "如果不做好充分准备就去弄材料很容易碰到危险的。也许会丢掉性命… 即使这样你也能弄来材料吗？"], {}, []], [3058, 0, "莉萨的特殊治疗剂Ⅲ", ["请把我做出来的特殊治疗剂拿给波达，波达伤口会马上完全康复的。"], "只要有莉萨的特殊治疗剂，就可以治好波达的伤口了…那我得快点去见波达！", ["在伤口周围好好涂抹一遍，伤口会在瞬间消失的。绝不能吃啊！！一定要记住。"], {}, []], [3104, 0, "再次收集妖精的号角", ["你好? 和#p2012019#聊得怎么样？啊? 哎呀…把 #t4031190#弄丢了? 这个…如何你想再和 #p2012019#聊聊，我可以再为你制作 #t4031190#。 只是材料需要你自己来准备。。。 可以吗?"], "#p2012012#说既然已经制作过一次，再次制作#t4031190#也不会很麻烦，只不过需要你自己准备材料. 比起上一次来说所需材料也较少，快去收集#b#t4000073# 50个#k和 #b#t4003004# 10个#k, #b#t4000021# 10个#k吧? \n\n#i4000073# #t4000073# #b#c4000073#/50#k\n#i4003004# #t4003004# #b#c4003004#/10 \n#i4000021# #t4000021# #b#c4000021#/10#k#k", ["既然制作过一次，这次的制造时间就会缩短，只要你把材料带来就行了，包括 #b#t4000073# 50个#k和 #b#t4003004# 10个#k, #b#t4000021# 10个#k。 只要有这些材料，我马上帮你制作 #t4031190#。"], {}, []], [3104, 1, "再次收集妖精的号角", ["#t4031190#材料收集齐全了吗? 好啊。 材料齐全了。这样我就可以制作 #t4031190#了。请稍等。。。", "好了, 这就是 #t4031190#。 制作过程比上次可顺利多了。 请妥善保管，小心不要再弄丢了。"], "#p2012012#说既然已经制作过一次，再次制作#t4031190#也不会很麻烦，只不过需要你自己准备材料. 比起上一次来说所需材料也较少，快去收集#b#t4000073# 50个#k和 #b#t4003004# 10个#k, #b#t4000021# 10个#k吧? \n\n#i4000073# #t4000073# #b#c4000073#/50#k\n#i4003004# #t4003004# #b#c4003004#/10 \n#i4000021# #t4000021# #b#c4000021#/10#k#k", ["如果又弄丢了#t4031190#,就来找我吧。只要带来材料,我会帮你重新制造的。"], {}, []], [3904, 1, "王妃的茶2", ["击退了#o5200000# 30只！真是感谢您。我这就去拿#t4031577#，请稍等？"], "#p2012012#说他不知道 #p2101007#是谁，但不能轻易让出#t4031577#，如果非常需要 #t4031577#的话，就击退 #r#o5200000# 30只#k。 \n\n#o5200000#  #r#a39041#", [], {}, []], [3904, 0, "王妃的茶2", ["有什么事吗？什么？找#t4031577#？这…… 这个不卖给人类…… 是#m260000000#的精灵#p2101007#订购的？#p2101007#……？好像没听说过这个名字哦…… 一定要茶叶吗？"], "#p2012012#说他不知道 #p2101007#是谁，但不能轻易让出#t4031577#，如果非常需要 #t4031577#的话，就击退 #r#o5200000# 30只#k。 \n\n#o5200000#  #r#a39041#", ["看来很需要茶叶哦。但是精灵的茶叶连精灵也很难获得…… 怎么办？啊！我给您茶叶，只要您答应我一件事？击退#m200000000# 周边的#r#o5200000##k #r30只#k就可以……", "之所以不把精灵之茶卖给人类是因为最近收获这个很少。精灵之茶是很纤细的植物，要在安静的地方用心栽培，但因为#o5200000#们而无法做到。所以希望您能帮我们击退他们。"], {}, []], [4200, 1, "芬拉的拜托", ["有什么事吗？找我做什么？你说什么？听到了有关我的传闻？说我实际长得很丑？化妆遮盖着？啊啊啊哦！说谎！是谁散布谣言的？（颤颤抖抖~）"], "芬拉对自己的外貌非常没有自信垂头丧气，追求美丽的欲望从没有放弃过。去找在天空之城的#b#p2012012##k，看看他是否有能变漂亮的秘方。。。", ["唔。。。够了。。我知道这是谁干的好事。。是博士！我要报仇，让他知道散布谣言的代价。怎么才能报复呢？我想一想，过一会儿在我跟谈谈吧。"], {}, []], [4201, 0, "莉萨的报复", ["算了。虽然说得有点儿对。还是很郁闷。你问我有什么方法能变漂亮是吗？我会告诉你秘方外加我的高级化妆品，但不是免费的。。。你要帮我做件事！怎么样？做个交易？"], "为了报复恶意散布谣言的#b#p2012017##k，给他拿去假冒的设计图。\n\n#t04031391# #b#c04031391#/1#k", ["一定是住在通天塔里的，专门搞些奇怪的研究的博士#b#p2012017##k散布的谣言！我想出了一个妙计报复。给秀兹一张假设计图，让他的实验做得一塌糊涂。", "给他这张设计图，说这是隐藏在玩具城时间塔里的传说中的设计图，并帮他按着假设计图收集所需要的材料。", "哈哈哈。。。我要亲眼看看，他失败的样子。"], {}, []], [4203, 1, "秀兹的冒牌实验", ["怎么样？计划成功了吧！干得好，我听说博士得了忧郁症！真是痛快~"], "跟预想的一样实验失败，虽然实验糟透了，我还是完成了任务。去找#b#p2012012##k。。。", ["既然你帮我报了仇，我就给你化妆品。秘籍我还没写好过一会儿你再来。"], {}, []], [4204, 0, "给芬拉的魔法化妆品", ["化妆品准备好了，拿给#p9250000#吧。"], "化妆品终于到手了，赶紧拿给 #b#p9250000##k。 \n\n#t04031392# #b#c04031392#/1#k", ["来~拿去吧。这可是我的高级化妆品。盒子里有化妆的方法。转告 #b#p9250000##k希望她也能像我一样变得漂亮。。。"], {}, []]], greeting="你好我叫莉萨";
var choices=[], picked=null, page=0, stage="menu", closed=false, started=false, origin=-1, rewardIndex=-1;
function finish(){closed=true;cm.dispose();}
function validPlace(){
    return cm.getNpc()==npcId && maps.indexOf(cm.getMapId())>=0 && (origin<0 || origin==cm.getMapId());
}
function ready(){
    var q=Packages.server.quest.MapleQuest.getInstance(picked[0]);
    return picked[1]==0 ? q.canStart(cm.getPlayer(),cm.getNpc()) : q.canComplete(cm.getPlayer(),cm.getNpc());
}
function start(){
    if(closed || started)return;
    started=true;
    if(!validPlace()){finish();return;}
    origin=cm.getMapId();
    var menu="";
    for(var i=0;i<entries.length;i++){
        var d=entries[i],q=Packages.server.quest.MapleQuest.getInstance(d[0]);
        if((d[1]==0 && q.canStart(cm.getPlayer(),cm.getNpc())) || (d[1]==1 && cm.getQuestStatus(d[0])==1)){
            menu+="\r\n#L"+choices.length+"#"+(d[1]==0?"[接受] ":"[继续] ")+d[2]+"#l";
            choices.push(d);
        }
    }
    if(choices.length==0){cm.sendOk(greeting+"\r\n\r\n当前没有可以交接的普通任务。");finish();return;}
    cm.sendSimple(greeting+"\r\n"+menu);
}
function showBefore(){
    var text=picked[3][page];
    if(picked[6][String(page)])cm.sendSimple(text);
    else if(page==picked[3].length-1)cm.sendYesNo(text);
    else cm.sendNext(text);
}
function commit(){
    if(!ready()){cm.sendOk(picked[4] || "任务条件尚未完成，请查看任务栏中的要求。");finish();return;}
    if(picked[7].length>0 && rewardIndex<0){
        stage="reward";
        var menu="请选择一件任务奖励：";
        for(var i=0;i<picked[7].length;i++)menu+="\r\n#L"+i+"##i"+picked[7][i][0]+"# #t"+picked[7][i][0]+"# × "+picked[7][i][1]+"#l";
        cm.sendSimple(menu);return;
    }
    closed=true;
    if(picked[7].length>0){
        // Native reward selection is zero based; client rewards here have no job/gender filters.
        var q=Packages.server.quest.MapleQuest.getInstance(picked[0]);
        var player=cm.getPlayer(),npc=cm.getNpc(),client=cm.getClient();
        cm.dispose();client.removeClickedNPC();
        q.complete(player,npc,java.lang.Integer.valueOf(rewardIndex),false);
    }else if(picked[1]==0)cm.startClientNpcQuest(picked[0]);
    else cm.completeClientNpcQuest(picked[0]);
}
function accepted(){
    if(picked[5].length==0){commit();return;}
    stage="after";page=0;cm.sendNext(picked[5][page]);
}
function action(mode,type,selection){
    if(closed)return;
    if(!validPlace() || mode!=1){finish();return;}
    if(stage=="menu"){
        if(selection<0 || selection>=choices.length || selection!=Math.floor(selection)){finish();return;}
        picked=choices[selection];
        if(!ready()){cm.sendOk(picked[4] || "任务条件尚未完成，请查看任务栏中的要求。");finish();return;}
        stage="before";page=0;showBefore();return;
    }
    if(stage=="before"){
        var answer=picked[6][String(page)];
        if(answer){
            if(answer.options.indexOf(selection)<0){finish();return;}
            if(selection!=answer.correct){
                if(answer.wrong.length>0)cm.sendOk(answer.wrong.join("\r\n"));
                finish();return;
            }
        }
        if(page<picked[3].length-1){page++;showBefore();return;}
        if(answer){stage="confirm";cm.sendYesNo(picked[2]);return;}
        accepted();return;
    }
    if(stage=="confirm"){accepted();return;}
    if(stage=="reward"){
        if(selection<0 || selection>=picked[7].length || selection!=Math.floor(selection)){finish();return;}
        rewardIndex=selection;commit();return;
    }
    if(stage=="after"){
        if(page<picked[5].length-1){page++;cm.sendNext(picked[5][page]);return;}
        commit();
    }
}
